using System;

namespace StdbModule;

public static partial class EnglishQuotes
{
    public static class WHAuden
    {
        public static readonly Quote[] Quotes = new Quote[]
        {
            new Quote { Id = "https://en.wikiquote.org/wiki/W._H._Auden", Text = "The basic stimulus to the intelligence is doubt, a feeling that the meaning of an experience is not self-evident.", Author = "W. H. Auden" },
            new Quote { Id = "https://en.wikiquote.org/wiki/W._H._Auden", Text = "To ask the hard question is simple, The simple act of the confused will.", Author = "W. H. Auden" },
            new Quote { Id = "https://en.wikiquote.org/wiki/W._H._Auden", Text = "Let us honour if we can The vertical man Though we value none But the horizontal one.", Author = "W. H. Auden" },
            new Quote { Id = "https://en.wikiquote.org/wiki/W._H._Auden", Text = "Acts of injustice done Between the setting and the rising sun In history lie like bones, each one.", Author = "W. H. Auden" },
            new Quote { Id = "https://en.wikiquote.org/wiki/W._H._Auden", Text = "When he laughed, respectable senators burst with laughter, And when he cried the little children died in the streets.", Author = "W. H. Auden" },
            new Quote { Id = "https://en.wikiquote.org/wiki/W._H._Auden", Text = "Sad is Eros, builder of cities, And weeping anarchic Aphrodite.", Author = "W. H. Auden" },
            new Quote { Id = "https://en.wikiquote.org/wiki/W._H._Auden", Text = "Base words are uttered only by the base And can for such at once be understood; But noble platitudes - ah, there's a case Where the most careful scrutiny is needed To tell a voice that's genuinely good From one that's base but merely has succeeded.", Author = "W. H. Auden" },
            new Quote { Id = "https://en.wikiquote.org/wiki/W._H._Auden", Text = "A poet is, before anything else, a person who is passionately in love with language.", Author = "W. H. Auden" },
            new Quote { Id = "https://en.wikiquote.org/wiki/W._H._Auden", Text = "To save your world you asked this man to die; Would this man, could he see you now, ask why?", Author = "W. H. Auden" },
            new Quote { Id = "https://en.wikiquote.org/wiki/W._H._Auden", Text = "How should we like it were stars to burn With a passion for us we could not return? If equal affection cannot be, Let the more loving one be me.", Author = "W. H. Auden" },
            new Quote { Id = "https://en.wikiquote.org/wiki/W._H._Auden", Text = "Marriage is rarely bliss But, surely it would be worse As particles to pelt At thousands of miles per sec About a universe In which a lover's kiss Would either not be felt Or break the loved one's neck.", Author = "W. H. Auden" },
            new Quote { Id = "https://en.wikiquote.org/wiki/W._H._Auden", Text = "Thoughts of his own death, like the distant roll of thunder at a picnic.", Author = "W. H. Auden" },
            new Quote { Id = "https://en.wikiquote.org/wiki/W._H._Auden", Text = "Cold, impossible, ahead Lifts the mountain's lovely head Whose white waterfall could bless Travellers in their last distress.", Author = "W. H. Auden" },
            new Quote { Id = "https://en.wikiquote.org/wiki/W._H._Auden", Text = "History to the defeated May say Alas but cannot help nor pardon.", Author = "W. H. Auden" },
            new Quote { Id = "https://en.wikiquote.org/wiki/W._H._Auden", Text = "The stars are dead. The animals will not look. We are left alone with our day, and the time is short, and History to the defeated May say Alas but cannot help nor pardon.", Author = "W. H. Auden" },
            new Quote { Id = "https://en.wikiquote.org/wiki/W._H._Auden", Text = "I'll love you, dear, I'll love you Till China and Africa meet, And the river jumps over the mountain And the salmon sing in the street, I'll love you till the ocean Is folded and hung up to dry And the seven stars go squawking Like geese about the sky.", Author = "W. H. Auden" },
            new Quote { Id = "https://en.wikiquote.org/wiki/W._H._Auden", Text = "O plunge your hands in water, Plunge them in up to the wrist; Stare, stare in the basin And wonder what you've missed. The glacier knocks in the cupboard, The desert sighs in the bed, And the crack in the tea-cup opens A lane to the land of the dead.", Author = "W. H. Auden" },
            new Quote { Id = "https://en.wikiquote.org/wiki/W._H._Auden", Text = "About suffering they were never wrong, The Old Masters.", Author = "W. H. Auden" },
            new Quote { Id = "https://en.wikiquote.org/wiki/W._H._Auden", Text = "They never forgot That even the most dreadful martyrdom must run its course Anyhow in a corner, some untidy spot Where the dogs go on with their doggy life and the torturer's horse Scratches its innocent behind on a tree.", Author = "W. H. Auden" },
            new Quote { Id = "https://en.wikiquote.org/wiki/W._H._Auden", Text = "I sit in one of the dives On Fifty-second Street Uncertain and afraid As the clever hopes expire Of a low dishonest decade: Waves of anger and fear Circulate over the bright And darkened lands of the earth, Obsessing our private lives; The unmentionable odour of death Offends the September night.", Author = "W. H. Auden" },
            new Quote { Id = "https://en.wikiquote.org/wiki/W._H._Auden", Text = "I and the public know What all schoolchildren learn, Those to whom evil is done Do evil in return.", Author = "W. H. Auden" },
            new Quote { Id = "https://en.wikiquote.org/wiki/W._H._Auden", Text = "Into this neutral air Where blind skyscrapers use Their full height to proclaim The strength of Collective Man, Each language pours its vain Competitive excuse.", Author = "W. H. Auden" },
            new Quote { Id = "https://en.wikiquote.org/wiki/W._H._Auden", Text = "The windiest militant trash Important Persons shout Is not so crude as our wish.", Author = "W. H. Auden" },
            new Quote { Id = "https://en.wikiquote.org/wiki/W._H._Auden", Text = "For the error bred in the bone Of each woman and each man Craves what it cannot have, Not universal love But to be loved alone.", Author = "W. H. Auden" },
            new Quote { Id = "https://en.wikiquote.org/wiki/W._H._Auden", Text = "Defenceless under the night Our world in stupor lies; Yet, dotted everywhere, Ironic points of light Flash out wherever the Just Exchange their messages: May I, composed like them Of Eros and of dust, Beleaguered by the same Negation and despair, Show an affirming flame.", Author = "W. H. Auden" },
            new Quote { Id = "https://en.wikiquote.org/wiki/W._H._Auden", Text = "We would rather be ruined than changed We would rather die in our dread Than climb the cross of the moment And let our illusions die.", Author = "W. H. Auden" },
            new Quote { Id = "https://en.wikiquote.org/wiki/W._H._Auden", Text = "A million eyes, a million boots in line, Without expression, waiting for a sign.", Author = "W. H. Auden" },
            new Quote { Id = "https://en.wikiquote.org/wiki/W._H._Auden", Text = "Out of the air a voice without a face Proved by statistics that some cause was just In tones as dry and level as the place: No one was cheered and nothing was discussed...", Author = "W. H. Auden" },
            new Quote { Id = "https://en.wikiquote.org/wiki/W._H._Auden", Text = "A crowd of ordinary decent folk Watched from without and neither moved nor spoke As three pale figures were led forth and bound To three posts driven upright in the ground.", Author = "W. H. Auden" },
            new Quote { Id = "https://en.wikiquote.org/wiki/W._H._Auden", Text = "A ragged urchin, aimless and alone, Loitered about that vacancy: a bird Flew up to safety from his well-aimed stone: That girls are raped, that two boys knife a third, Were axioms to him, who'd never heard Of any world where promises were kept Or one could weep because another wept.", Author = "W. H. Auden" },
            new Quote { Id = "https://en.wikiquote.org/wiki/W._H._Auden", Text = "The thin-lipped armorer, Hephaestos, hobbled away, Thetis of the shining breasts Cried out in dismay At what the god had wrought To please her son, the strong Iron-hearted man-slaying Achilles Who would not live long.", Author = "W. H. Auden" },
            new Quote { Id = "https://en.wikiquote.org/wiki/W._H._Auden", Text = "The surest sign that a man has a genuine taste of his own is that he is uncertain of it.", Author = "W. H. Auden" },
            new Quote { Id = "https://en.wikiquote.org/wiki/W._H._Auden", Text = "In general, when reading a scholarly critic, one profits more from his quotations than from his comments.", Author = "W. H. Auden" },
            new Quote { Id = "https://en.wikiquote.org/wiki/W._H._Auden", Text = "Some books are undeservedly forgotten; none are undeservedly remembered.", Author = "W. H. Auden" },
            new Quote { Id = "https://en.wikiquote.org/wiki/W._H._Auden", Text = "One cannot review a bad book without showing off.", Author = "W. H. Auden" },
            new Quote { Id = "https://en.wikiquote.org/wiki/W._H._Auden", Text = "No poet or novelist wishes he were the only one who ever lived, but most of them wish they were the only one alive, and quite a number fondly believe their wish has been granted.", Author = "W. H. Auden" },
            new Quote { Id = "https://en.wikiquote.org/wiki/W._H._Auden", Text = "Without Art, we should have no notion of the sacred; without Science, we should always worship false gods.", Author = "W. H. Auden" },
            new Quote { Id = "https://en.wikiquote.org/wiki/W._H._Auden", Text = "When I find myself in the company of scientists, I feel like a shabby curate who has strayed by mistake into a drawing room full of dukes.", Author = "W. H. Auden" },
            new Quote { Id = "https://en.wikiquote.org/wiki/W._H._Auden", Text = "What the mass media offer is not popular art, but entertainment which is intended to be consumed like food, forgotten, and replaced by a new dish. This is bad for everyone; the majority lose all genuine taste of their own, and the minority become cultural snobs.", Author = "W. H. Auden" },
            new Quote { Id = "https://en.wikiquote.org/wiki/W._H._Auden", Text = "All poets adore explosions, thunderstorms, tornadoes, conflagrations, ruins, scenes of spectacular carnage. The poetic imagination is not at all a desirable quality in a statesman.", Author = "W. H. Auden" },
            new Quote { Id = "https://en.wikiquote.org/wiki/W._H._Auden", Text = "Every autobiography is concerned with two characters, a Don Quixote, the Ego, and a Sancho Panza, the Self.", Author = "W. H. Auden" },
            new Quote { Id = "https://en.wikiquote.org/wiki/W._H._Auden", Text = "The image of myself which I try to create in my own mind in order that I may love myself is very different from the image which I try to create in the minds of others in order that they may love me.", Author = "W. H. Auden" },
            new Quote { Id = "https://en.wikiquote.org/wiki/W._H._Auden", Text = "Almost all of our relationships begin and most of them continue as forms of mutual exploitation, a mental or physical barter, to be terminated when one or both parties run out of goods.", Author = "W. H. Auden" },
            new Quote { Id = "https://en.wikiquote.org/wiki/W._H._Auden", Text = "To have a sense of sin means to feel guilty at there being an ethical choice to make, a guilt which, however \"good\" I may become, remains unchanged.", Author = "W. H. Auden" },
            new Quote { Id = "https://en.wikiquote.org/wiki/W._H._Auden", Text = "The law cannot forgive, for the law has not been wronged, only broken; only persons can be wronged. The law can pardon, but it can only pardon what it has the power to punish.", Author = "W. H. Auden" },
            new Quote { Id = "https://en.wikiquote.org/wiki/W._H._Auden", Text = "All pity is self-pity.", Author = "W. H. Auden" },
            new Quote { Id = "https://en.wikiquote.org/wiki/W._H._Auden", Text = "To some degree every American poet feels that the whole responsibility for contemporary poetry has fallen upon his shoulders, that he is a literary aristocracy of one.", Author = "W. H. Auden" },
            new Quote { Id = "https://en.wikiquote.org/wiki/W._H._Auden", Text = "Among those whom I like or admire, I can find no common denominator, but among those whom I love, I can: all of them make me laugh.", Author = "W. H. Auden" },
            new Quote { Id = "https://en.wikiquote.org/wiki/W._H._Auden", Text = "A vice in common can be the ground of a friendship but not a virtue in common. X and Y may be friends ''because'' they are both drunkards or womanizers but, if they are both sober and chaste, they are friends for some other reason.", Author = "W. H. Auden" },
            new Quote { Id = "https://en.wikiquote.org/wiki/W._H._Auden", Text = "Unfortunately for the modern dramatist, during the past century and a half the public realm has been less and less of a realm where human deeds are done, and more and more of a realm of mere human behavior. The contemporary dramatist has lost his natural subject.", Author = "W. H. Auden" },
            new Quote { Id = "https://en.wikiquote.org/wiki/W._H._Auden", Text = "When one looks into the window of a store which sells devotional art objects, one can't help wishing the iconoclasts had won.", Author = "W. H. Auden" },
            new Quote { Id = "https://en.wikiquote.org/wiki/W._H._Auden", Text = "No opera plot can be sensible, for people do not sing when they are feeling sensible.", Author = "W. H. Auden" },
            new Quote { Id = "https://en.wikiquote.org/wiki/W._H._Auden", Text = "From the moment the first flint was flaked this landing was merely a matter of time. But our selves, like Adam's, still don't fit us exactly, modern only in this-our lack of decorum.", Author = "W. H. Auden" },
            new Quote { Id = "https://en.wikiquote.org/wiki/W._H._Auden", Text = "Politics cannot be a science, because in politics theory and practice cannot be separated, and the sciences depend upon their separation.", Author = "W. H. Auden" },
            new Quote { Id = "https://en.wikiquote.org/wiki/W._H._Auden", Text = "All sin tends to be addictive, and the terminal point of addiction is what is called damnation.", Author = "W. H. Auden" },
            new Quote { Id = "https://en.wikiquote.org/wiki/W._H._Auden", Text = "A god who is both self-sufficient and content to remain so could not interest us enough to raise the question of his existence.", Author = "W. H. Auden" },
            new Quote { Id = "https://en.wikiquote.org/wiki/W._H._Auden", Text = "Whatever the field under discussion, those who engage in debate must not only believe in each other's good faith, but also in their capacity to arrive at the truth.", Author = "W. H. Auden" },
            new Quote { Id = "https://en.wikiquote.org/wiki/W._H._Auden", Text = "I do not believe an artist's life throws much light upon his works. I do believe, however, that, more often than most people realize, his works may throw light upon his life. An artist with certain imaginative ideas in his head may then involve himself in relationships which are congenial to them.", Author = "W. H. Auden" },
            new Quote { Id = "https://en.wikiquote.org/wiki/W._H._Auden", Text = "A craftsman knows in advance what the finished result will be, while the artist knows only what it will be when he has finished it. But it is unbecoming in an artist to talk about inspiration; that is the reader's business.", Author = "W. H. Auden" },
            new Quote { Id = "https://en.wikiquote.org/wiki/W._H._Auden", Text = "Money is the necessity that frees us from necessity. Of all novelists in any country, Trollope best understands the role of money. Compared with him even Balzac is a romantic.", Author = "W. H. Auden" },
            new Quote { Id = "https://en.wikiquote.org/wiki/W._H._Auden", Text = "Most people call something profound, not because it is near some important truth but because it is distant from ordinary life. Thus, darkness is profound to the eye, silence to the ear; what-is-not is the profundity of what-is.", Author = "W. H. Auden" },
            new Quote { Id = "https://en.wikiquote.org/wiki/W._H._Auden", Text = "Young people, who are still uncertain of their identity, often try on a succession of masks in the hope of finding the one which suits them - the one, in fact, which is not a mask.", Author = "W. H. Auden" },
            new Quote { Id = "https://en.wikiquote.org/wiki/W._H._Auden", Text = "Most people are even less original in their dreaming than in their waking life; their dreams are more monotonous than their thoughts and oddly enough, more literary.", Author = "W. H. Auden" },
            new Quote { Id = "https://en.wikiquote.org/wiki/W._H._Auden", Text = "In all technologically \"advanced\" countries, fashion has replaced tradition, so that involuntary membership in a society can no longer provide a feeling of community.", Author = "W. H. Auden" },
            new Quote { Id = "https://en.wikiquote.org/wiki/W._H._Auden", Text = "It is, for example, axiomatic that we should all think of ourselves as being more sensitive than other people because, when we are insensitive in our dealings with others, we cannot be aware of it at the time: conscious insensitivity is a self-contradiction.", Author = "W. H. Auden" },
            new Quote { Id = "https://en.wikiquote.org/wiki/W._H._Auden", Text = "In any modern city, a great deal of our energy has to be expended in ''not'' seeing, ''not'' hearing, ''not'' smelling. An inhabitant of New York who possessed the sensory acuteness of an African Bushman would very soon go mad.", Author = "W. H. Auden" },
            new Quote { Id = "https://en.wikiquote.org/wiki/W._H._Auden", Text = "One can only blaspheme if one believes.", Author = "W. H. Auden" },
            new Quote { Id = "https://en.wikiquote.org/wiki/W._H._Auden", Text = "Genealogies are admirable things, provided they do not encourage the curious delusion that some families are older than others.", Author = "W. H. Auden" },
            new Quote { Id = "https://en.wikiquote.org/wiki/W._H._Auden", Text = "Normally, when one passes someone on the street who is in pain, one either tries to help him, or one simply looks the other way. With a photo there's no human decision; you're not there; you can't turn away; you simply gape. It's a form of voyeurism.", Author = "W. H. Auden" },
            new Quote { Id = "https://en.wikiquote.org/wiki/W._H._Auden", Text = "It's frightfully important for a writer to be his age, not to be younger or older than he is. One might ask, \"What should I write at the age of sixty-four,\" but never, \"What should I write in 1940.\"", Author = "W. H. Auden" },
            new Quote { Id = "https://en.wikiquote.org/wiki/W._H._Auden", Text = "A poet, ''qua'' poet, has only one political duty, namely, in his own writing to set an example of the correct use of his mother tongue, which is always being corrupted. When words lose their meaning, physical force takes over.", Author = "W. H. Auden" },
            new Quote { Id = "https://en.wikiquote.org/wiki/W._H._Auden", Text = "I never write when I'm drunk. Why should one need aids? The Muse is a high-spirited girl who doesn't like to be brutally or coarsely wooed. And she doesn't like slavish devotion - then she lies.", Author = "W. H. Auden" },
            new Quote { Id = "https://en.wikiquote.org/wiki/W._H._Auden", Text = "I don't think the mystical experience can be verbalized. When the ego disappears, so does power over language.", Author = "W. H. Auden" },
            new Quote { Id = "https://en.wikiquote.org/wiki/W._H._Auden", Text = "Every day America's destroyed and re-created, America is what you do, America is I and you, America is what you choose to make it.", Author = "W. H. Auden" },
            new Quote { Id = "https://en.wikiquote.org/wiki/W._H._Auden", Text = "A real book reads us.", Author = "W. H. Auden" },
        };
    }
}